import{a as e,c as t,i as n,t as r}from"./app-B8uz0aqq.js";var i=JSON.parse(`{"path":"/33-BigWorld_Compatibility.html","title":"BigWorld Compatibility Layer (Apollo)","lang":"en-US","frontmatter":{},"filePathRelative":"33-BigWorld_Compatibility.md","git":{"createdTime":1767059850000,"updatedTime":1767059850000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"}]}}`),a={name:`33-BigWorld_Compatibility.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="bigworld-compatibility-layer-apollo" tabindex="-1"><a class="header-anchor" href="#bigworld-compatibility-layer-apollo"><span>BigWorld Compatibility Layer (Apollo)</span></a></h1><p>Status: <strong>Incremental</strong>. This is a BigWorld-style C++ API facade built on top of Apollo, not a full BigWorld engine/runtime.</p><h2 id="goal" tabindex="-1"><a class="header-anchor" href="#goal"><span>Goal</span></a></h2><p>Provide a familiar <code>BigWorld::*</code> C++ API surface for game/server logic while reusing Apollo infrastructure. The compatibility layer is designed to be:</p><ul><li><strong>KISS</strong>: a small, explicit runtime with an update loop</li><li><strong>YAGNI</strong>: only the APIs we actually use are implemented</li><li><strong>Testable</strong>: every exposed API has a runnable test case</li></ul><h2 id="implemented-apis-current" tabindex="-1"><a class="header-anchor" href="#implemented-apis-current"><span>Implemented APIs (current)</span></a></h2><p>Headers:</p><ul><li><code>include/bigworld/BigWorld.h</code>: public <code>BigWorld::*</code> facade</li><li><code>include/apollo/bw/*</code>: implementation types (<code>Runtime</code>, <code>Entity</code>, ids)</li></ul><p>Implementation:</p><ul><li><code>src/apollo/bw/runtime.cpp</code></li></ul><h3 id="global-facade-bigworld" tabindex="-1"><a class="header-anchor" href="#global-facade-bigworld"><span>Global facade (<code>BigWorld::*</code>)</span></a></h3><ul><li>Time: <ul><li><code>double BigWorld::time()</code></li><li><code>uint64_t BigWorld::timeMs()</code></li><li><code>void BigWorld::update()</code></li></ul></li><li>Entity registry: <ul><li><code>registerEntityFactory(typeName, factory)</code></li><li><code>createEntity(typeName)</code></li><li><code>entity(id)</code></li><li><code>entities()</code></li><li><code>destroyEntity(id)</code></li></ul></li><li>Timers (global): <ul><li><code>addTimer(initialOffsetSeconds, repeatOffsetSeconds, fn, userArg)</code></li><li><code>delTimer(timerId)</code></li></ul></li><li>One-shot callbacks: <ul><li><code>callback(delaySeconds, fn)</code></li><li><code>cancelCallback(callbackId)</code></li></ul></li></ul><h3 id="entity-base-class-bigworld-entity" tabindex="-1"><a class="header-anchor" href="#entity-base-class-bigworld-entity"><span>Entity base class (<code>BigWorld::Entity</code>)</span></a></h3><ul><li>Identity: <ul><li><code>EntityId id() const</code></li><li><code>const std::string&amp; typeName() const</code></li></ul></li><li>Entity timers: <ul><li><code>TimerId addTimer(initialOffsetSeconds, repeatOffsetSeconds, userArg)</code></li><li><code>bool delTimer(timerId)</code></li></ul></li><li>Destruction: <ul><li><code>bool destroy()</code></li></ul></li><li>Lifecycle hooks: <ul><li><code>onEnterWorld()</code></li><li><code>onLeaveWorld()</code></li><li><code>onDestroy()</code></li><li><code>onTimer(timerId, userArg)</code></li></ul></li></ul><h2 id="semantics-important" tabindex="-1"><a class="header-anchor" href="#semantics-important"><span>Semantics (important)</span></a></h2><h3 id="update-loop" tabindex="-1"><a class="header-anchor" href="#update-loop"><span>Update loop</span></a></h3><p>Timers are only dispatched when <code>BigWorld::update()</code> is called. You must call it periodically (e.g. per tick/frame) from your main loop.</p><h3 id="timer-units-and-behavior" tabindex="-1"><a class="header-anchor" href="#timer-units-and-behavior"><span>Timer units and behavior</span></a></h3><ul><li>Time parameters are <strong>seconds</strong> (<code>double</code>).</li><li>Negative offsets are clamped to <code>0</code>.</li><li><code>repeatOffsetSeconds == 0</code> means <strong>one-shot</strong> timer.</li></ul><p>Timer cancellation rules (intentionally separated):</p><ul><li><code>Entity::delTimer()</code> cancels <strong>entity timers</strong> created by that entity.</li><li><code>BigWorld::delTimer()</code> cancels <strong>global timers</strong> created by <code>BigWorld::addTimer()</code>.</li><li><code>BigWorld::cancelCallback()</code> cancels <strong>callback timers</strong> created by <code>BigWorld::callback()</code>.</li></ul><p>Cross-type cancellation returns <code>false</code> by design.</p><h3 id="threading-safety" tabindex="-1"><a class="header-anchor" href="#threading-safety"><span>Threading / safety</span></a></h3><p>Current implementation is <strong>single-threaded</strong> (no locks). Call <code>BigWorld::*</code> APIs from one thread.</p><h3 id="exceptions" tabindex="-1"><a class="header-anchor" href="#exceptions"><span>Exceptions</span></a></h3><p>Exceptions thrown from user callbacks or entity <code>onTimer()</code> are caught and ignored to keep the runtime stable.</p><h2 id="quick-start" tabindex="-1"><a class="header-anchor" href="#quick-start"><span>Quick start</span></a></h2><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&quot;bigworld/BigWorld.h&quot;</span></span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">struct</span> <span class="token class-name">Avatar</span> <span class="token keyword">final</span> <span class="token operator">:</span> BigWorld<span class="token double-colon punctuation">::</span>Entity <span class="token punctuation">{</span></span>
<span class="line">    <span class="token function">Avatar</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">:</span> <span class="token function">Entity</span><span class="token punctuation">(</span><span class="token string">&quot;Avatar&quot;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">onEnterWorld</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">override</span> <span class="token punctuation">{</span> <span class="token comment">/* ... */</span> <span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">onTimer</span><span class="token punctuation">(</span>TimerId id<span class="token punctuation">,</span> <span class="token keyword">int32_t</span> arg<span class="token punctuation">)</span> <span class="token keyword">override</span> <span class="token punctuation">{</span> <span class="token comment">/* ... */</span> <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">int</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token class-name">BigWorld</span><span class="token double-colon punctuation">::</span><span class="token function">registerEntityFactory</span><span class="token punctuation">(</span><span class="token string">&quot;Avatar&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">return</span> std<span class="token double-colon punctuation">::</span><span class="token generic-function"><span class="token function">make_shared</span><span class="token generic class-name"><span class="token operator">&lt;</span>Avatar<span class="token operator">&gt;</span></span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">auto</span> e <span class="token operator">=</span> <span class="token class-name">BigWorld</span><span class="token double-colon punctuation">::</span><span class="token function">createEntity</span><span class="token punctuation">(</span><span class="token string">&quot;Avatar&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">    e<span class="token operator">-&gt;</span><span class="token function">addTimer</span><span class="token punctuation">(</span><span class="token number">0.1</span><span class="token punctuation">,</span> <span class="token number">1.0</span><span class="token punctuation">,</span> <span class="token number">7</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token punctuation">;</span><span class="token punctuation">;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token class-name">BigWorld</span><span class="token double-colon punctuation">::</span><span class="token function">update</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token comment">// sleep/tick...</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="tests" tabindex="-1"><a class="header-anchor" href="#tests"><span>Tests</span></a></h2><p>All exposed APIs are covered by:</p><ul><li><code>tests/test_bigworld_api.cpp</code></li></ul><p>CTest target:</p><ul><li><code>BigWorldApiTests</code></li></ul><h3 id="api-coverage-mapping" tabindex="-1"><a class="header-anchor" href="#api-coverage-mapping"><span>API coverage mapping</span></a></h3><ul><li><code>time()/timeMs()/update()</code> → <code>test_time_monotonic</code>, <code>test_update_required_for_callback_dispatch</code></li><li>Entity lifecycle APIs → <code>test_factory_and_entity_lifecycle</code>, <code>test_factory_invalid_inputs_and_factory_returns_null</code></li><li>Entity timer APIs → <code>test_entity_timer_api</code>, <code>test_addTimer_invalid_clamp_and_cross_cancel</code></li><li>Callback APIs → <code>test_bigworld_callback_api</code>, <code>test_callback_empty_and_exceptions_swallowed</code></li><li>Global timer APIs → <code>test_bigworld_global_timer_api</code>, <code>test_addTimer_invalid_clamp_and_cross_cancel</code></li></ul><h2 id="not-implemented-yet-roadmap" tabindex="-1"><a class="header-anchor" href="#not-implemented-yet-roadmap"><span>Not implemented yet (roadmap)</span></a></h2><p>This compatibility layer does <strong>not</strong> yet provide:</p><ul><li>BigWorld Base/Cell split, mailboxes, and distributed entity routing</li><li>EntityDefs/IDL and automatic property replication</li><li>Python scripting compatibility</li><li>Network protocol compatibility with official BigWorld clients</li></ul><p>When you specify the exact BigWorld API surface/version you want (BaseApp/CellApp, mailbox semantics, scripting language), the next step is to extend this layer incrementally with the same “API + tests” rule.</p>`,39)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};